with msa(skill_key, bereich) as (values ('zahl_potenz_zehner','arithmetik_algebra'),('zahl_potenz_negativ','arithmetik_algebra'),('zahl_potenz_rechnen','arithmetik_algebra'),('zahl_potenz_gesetze','arithmetik_algebra'),('potenzen','arithmetik_algebra'),('zahl_wurzel_irrational','arithmetik_algebra'),('zahl_wurzel_quadrat','arithmetik_algebra'),('zahl_wurzel_naeherung','arithmetik_algebra'),('zahl_wurzel_teilweise','arithmetik_algebra'),('zahl_wurzel_gesetze','arithmetik_algebra'),('gleichung_lgs_addition','arithmetik_algebra'),('gleichung_lgs_einsetzen','arithmetik_algebra'),('gleichung_lgs_gleichsetzen','arithmetik_algebra'),('gleichung_lgs_grafisch','arithmetik_algebra'),('gleichung_quadr_wurzel','arithmetik_algebra'),('gleichung_quadr_faktor','arithmetik_algebra'),('gleichung_quadr_formel','arithmetik_algebra'),('gleichung_quadr_anzahl','arithmetik_algebra'),('fkt_exp_gleichung','arithmetik_algebra'),('gleichung_lgs_sachaufgabe','arithmetik_algebra'),('fkt_exp_anwendung','arithmetik_algebra'),('fkt_quadr_extrem','arithmetik_algebra'),('fkt_linear_graph','funktionen'),('fkt_linear_gleichung','funktionen'),('fkt_quadr_parabel','funktionen'),('fkt_exp_term','funktionen'),('fkt_sinus_graph','funktionen'),('fkt_linear_steigung','funktionen'),('fkt_linear_yabschnitt','funktionen'),('fkt_quadr_scheitel','funktionen'),('fkt_quadr_normalform','funktionen'),('fkt_linear_nullstelle','funktionen'),('fkt_quadr_nullstellen','funktionen'),('fkt_exp_halbwert','funktionen'),('prozent_zins_zinseszins','funktionen'),('fkt_exp_wachstum','funktionen'),('fkt_sinus_periodisch','funktionen'),('geo_koerper_zylinder','geometrie'),('geo_koerper_pyramide','geometrie'),('geo_koerper_kegel','geometrie'),('geo_koerper_kugel','geometrie'),('geo_massstab','geometrie'),('geo_aehnlich_streckfaktor','geometrie'),('geo_kreis_umfang','geometrie'),('geo_kreis_flaeche','geometrie'),('geo_kreis_sektor','geometrie'),('geo_kreis_rueck','geometrie'),('geo_kreis_zusammen','geometrie'),('geo_pythagoras_hypotenuse','geometrie'),('geo_pythagoras_kathete','geometrie'),('geo_pythagoras_umkehrung','geometrie'),('geo_pythagoras_anwendung','geometrie'),('geo_pythagoras_abstand','geometrie'),('geo_aehnlich_strahlen_abschnitt','geometrie'),('geo_aehnlich_strahlen_parallel','geometrie'),('geo_aehnlich_flaeche','geometrie'),('geo_winkel_thales','geometrie'),('geo_trigo_verhaeltnis','geometrie'),('geo_trigo_seite','geometrie'),('geo_trigo_winkel','geometrie'),('geo_trigo_anwendung','geometrie'),('stoch_pfad_produkt','stochastik'),('stoch_pfad_summe','stochastik'),('stoch_bedingt_irrefuehrend','stochastik'),('vorzeichen_add_sub','arithmetik_algebra'),('vorzeichen_mult_div','arithmetik_algebra'),('vorzeichen_vorrang','arithmetik_algebra'),('bruch_mult','arithmetik_algebra'),('bruch_div','arithmetik_algebra'),('term_zusammenfassen','arithmetik_algebra'),('term_ausmultiplizieren','arithmetik_algebra'),('term_minusklammer','arithmetik_algebra'),('term_ausklammern','arithmetik_algebra'),('term_einsetzen','arithmetik_algebra'),('term_binom_quadrat','arithmetik_algebra'),('term_binom_quadratdifferenz','arithmetik_algebra'),('term_binom_faktorisieren','arithmetik_algebra'),('term_binom_gemischt','arithmetik_algebra'),('gleichung_einschrittig','arithmetik_algebra'),('gleichung_zweischrittig','arithmetik_algebra'),('gleichung_beidseitig','arithmetik_algebra'),('gleichung_neg_koeffizient','arithmetik_algebra'),('gleichung_modellieren','arithmetik_algebra'),('proportionalitaet','funktionen'),('prozent_prozentwert','funktionen'),('prozent_prozentsatz','funktionen'),('prozent_grundwert','funktionen'),('prozent_veraenderung','funktionen'),('prozent_zins_jahreszins','funktionen'),('prozent_zins_teilzins','funktionen'),('prozent_zins_rueckrechnung','funktionen'),('geo_flaeche_dreieck','geometrie'),('geo_flaeche_trapez','geometrie'),('geo_flaeche_drachen_raute','geometrie'),('geo_flaeche_zusammengesetzt','geometrie'),('geo_flaeche_rueck','geometrie'),('geo_flaeche_term','geometrie'),('geo_umfang','geometrie'),('geo_volumen_quader','geometrie'),('geo_koerper_prisma','geometrie'),('groessen_volumen','geometrie'),('geo_winkel_summe','geometrie'),('geo_winkel_neben_scheitel','geometrie'),('geo_winkel_parallelen','geometrie'),('geo_winkel_dreieck','geometrie'),('stoch_kenngroessen','stochastik'),('stoch_laplace','stochastik'),('stoch_gegenereignis','stochastik'),('groessen_laengen','arithmetik_algebra'),('groessen_massen','arithmetik_algebra'),('groessen_zeit','arithmetik_algebra'),('groessen_flaechen','arithmetik_algebra'),('groessen_gemischt','arithmetik_algebra'),('runden_ueberschlag','arithmetik_algebra'),('bruch_kuerzen','arithmetik_algebra'),('bruch_dezimal','arithmetik_algebra'),('bruch_add','arithmetik_algebra'),('dezimal_add_sub','arithmetik_algebra'),('dezimal_mult','arithmetik_algebra'),('dezimal_div','arithmetik_algebra'),('geo_flaeche_rechteck','geometrie'),('geo_koordinaten','geometrie'))
, b as (select r.* from lsa_skill_bereit_roh(null) r),
z as (select * from pruef_ziel_roh()),
l as (select distinct skill_key from pruef_ziel_liste() where abschnitt='gezielt')
select m.bereich, count(*) n, count(*) filter (where k.skill_key is null) fehlt_in_skills,
  count(*) filter (where b.erfuellt) bereit, count(*) filter (where not b.erfuellt and b.texte_im_pool>=1) teil,
  count(*) filter (where b.texte_im_pool=0) offen, sum(greatest(b.fehlende_texte,b.fehlende_ohne_mc)) fehl_texte,
  count(*) filter (where z.skill_key is not null and l.skill_key is null) nicht_in_liste,
  sum(least(z.rest, cardinality(z.task_ids))) filter (where l.skill_key is null) vorschl_nicht_in_liste,
  sum(cardinality(z.task_ids)) filter (where l.skill_key is null) ids_nicht_in_liste
from msa m left join skills k using(skill_key) left join b using(skill_key) left join z using(skill_key) left join l using(skill_key)
group by rollup(1) order by 1;
